SELECT id, superhero_name, SUM(height_cm) * 1.0 / COUNT(*) AS average_height
FROM superhero
GROUP BY id, superhero_name;

SELECT SUM(CASE WHEN c.colour = 'Blue' THEN 1 ELSE 0 END) * 100.0 / COUNT(s.superhero_name) AS percentage
FROM superhero s
JOIN colour c ON s.eye_colour_id = c.id;

SELECT SUM(p.publisher_name = 'DC Comics') - SUM(p.publisher_name = 'Marvel Comics') AS difference
FROM superhero s
JOIN publisher p ON s.publisher_id = p.id;

SELECT CAST(SUM(CASE WHEN Patient.SEX = 'M' AND Laboratory.UA <= '8.0' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN Patient.SEX = 'F' AND Laboratory.UA <= '6.5' THEN 1 ELSE 0 END) AS male_to_female_ratio
FROM Patient
INNER JOIN Laboratory ON Patient.ID = Laboratory.ID;

SELECT SUM(Diagnosis LIKE '%ITP%') * 100.0 / SUM(Diagnosis LIKE '%SLE%')
FROM Examination
WHERE Symptoms LIKE '%thrombocytopenia%';

SELECT COUNT(DISTINCT CASE WHEN PLT < 100 THEN ID END) - COUNT(DISTINCT CASE WHEN PLT > 400 THEN ID END) AS lower_vs_higher
FROM Laboratory
WHERE PLT <= 100 OR PLT >= 400;

SELECT atom_id, atom_id2
FROM connected
WHERE bond_id = 'TR000_2_5';

SELECT bond_id
FROM connected
WHERE atom_id2 = (SELECT atom_id2 FROM connected WHERE atom_id = 'TR000_2');

SELECT ROUND(SUM(bond_type = '=') * 100.0 / COUNT(bond_id), 5) AS percent
FROM bond
WHERE molecule_id = 'TR008';

SELECT SUM(bond_type = ' = ') * 100.0 / COUNT(bond_id) AS percent
FROM bond
WHERE molecule_id = 'TR047';

SELECT SUM(CASE WHEN molecule.label = '+' AND atom.element = 'h' THEN 1 ELSE 0 END) * 100.0 / COUNT(molecule.molecule_id) AS percentage
FROM atom
JOIN molecule ON molecule.molecule_id = atom.molecule_id;

SELECT atom_id, element
FROM atom
WHERE molecule_id = 'TR186';

SELECT CAST(SUM(CASE WHEN m.label = '+' AND a.element = 'cl' THEN 1 ELSE 0 END) AS REAL) / COUNT(a.molecule_id) AS percentage
FROM atom a
JOIN molecule m ON a.molecule_id = m.molecule_id;

SELECT CASE WHEN EXISTS (
    SELECT 1 FROM molecule WHERE molecule_id = 'TR124' AND label = '+'
) THEN 'yes' ELSE 'no' END AS is_carcinogenic

SELECT `FRPM Count (Ages 5-17)`
FROM frpm
WHERE CDSCode = (SELECT cds FROM satscores ORDER BY AvgScrRead DESC LIMIT 1);

SELECT COUNT(DISTINCT CDSCode) AS total_schools
FROM schools
WHERE MailCity = 'Hickman' AND CharterNum = '00D4';

SELECT GSoffered
FROM schools
WHERE ABS(Longitude) = (SELECT MAX(ABS(Longitude)) FROM schools);

WITH user_id AS (
  SELECT Id FROM users WHERE DisplayName = 'csgillespie'
)
SELECT p.Title
FROM posts p
JOIN user_id u ON p.OwnerUserId = u.Id;

WITH user_id AS (
  SELECT Id FROM users WHERE DisplayName = 'csgillespie'
)
SELECT COUNT(*) AS BadgeCount
FROM badges
WHERE UserId IN (SELECT Id FROM user_id);

WITH user_votes AS (
  SELECT * FROM votes WHERE UserId = 58
),
votes_on_date AS (
  SELECT * FROM user_votes WHERE CreationDate = '2010-07-19'
)
SELECT COUNT(*) AS vote_count
FROM votes_on_date;

WITH vote_user AS (
    SELECT UserId FROM votes WHERE Id = 6347
)
SELECT users.DisplayName
FROM users
JOIN vote_user ON users.Id = vote_user.UserId;

WITH target_post AS (
    SELECT Id FROM posts WHERE Title LIKE '%data visualization%'
)
SELECT COUNT(*) AS vote_count
FROM votes
WHERE PostId = (SELECT Id FROM target_post);

SELECT Text
FROM comments
WHERE UserId = (SELECT Id FROM users WHERE DisplayName = 'A Lion.');

SELECT Id AS post_id, OwnerUserId AS user_id
FROM posts
WHERE Score > 60;

SELECT COUNT(DISTINCT UserId) AS NumUsers
FROM badges
WHERE Name = 'Announcer';

SELECT COUNT(*) AS adult_users
FROM users
WHERE Age BETWEEN 19 AND 65;

SELECT DisplayName
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

SELECT DisplayName, Age
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

WITH votes_2011 AS (
    SELECT * FROM votes WHERE YEAR(CreationDate) = 2011
),
votes_2011_bounty50 AS (
    SELECT * FROM votes_2011 WHERE BountyAmount = 50
)
SELECT COUNT(DISTINCT PostId) FROM votes_2011_bounty50;

WITH min_age AS (
  SELECT MIN(Age) AS MinAge FROM users
)
SELECT Id
FROM users, min_age
WHERE Age = min_age.MinAge;

SELECT DisplayName
FROM users
WHERE Reputation = (SELECT MAX(Reputation) FROM users);

SELECT COUNT(*) AS user_count
FROM (
    SELECT *
    FROM (
        SELECT *
        FROM users
        WHERE Reputation > 2000
    ) AS reputation_users
    WHERE Views > 1000
) AS filtered_users;

SELECT DISTINCT DisplayName
FROM users
WHERE Age BETWEEN 19 AND 65;

SELECT CreationDate
FROM users
WHERE Id = (SELECT Id FROM users WHERE DisplayName = 'IrishStat');

WITH eur AS (
  SELECT COUNT(*) AS cnt FROM customers WHERE Currency = 'EUR'
),
czk AS (
  SELECT COUNT(*) AS cnt FROM customers WHERE Currency = 'CZK'
)
SELECT CAST(eur.cnt AS REAL) / czk.cnt AS ratio
FROM eur, czk;

SELECT COUNT(CASE WHEN Currency = 'Euro' THEN 1 END) * 100.0 / COUNT(*) AS percentage
FROM customers
WHERE Segment = 'KAM';

SELECT ProductID
FROM transactions_1k
WHERE Date = '2012-08-23' AND Time = '21:20:00';

SELECT defensive_work_rate
